          status.textContent = job.state === "saved" ? `Saved ${job.name ?? "CSV"}.` : "CSV save canceled.";
          exportJob = null;
          return;
        }
        if (job.state === "failed")
          throw new Error(job.message ?? "CSV export failed");
        if (job.state !== "choosing" && job.state !== "writing")
          throw new Error("Unknown CSV export state");
      }
      throw new Error("CSV save timed out");
    } catch (error) {
      if (gen === generation) {
        await cancelExport();
        report(error);
      }
    } finally {
      exportBusy = false;
      setControls();
    }
  }
  async function refresh(force = false) {
    if (closed || !client) return;
    const op = ++bindOp;
    try {
      const env = await client.environment.get();
      if (op !== bindOp || closed) return;
      applyAppearance(document.documentElement, env.appearance);
      const systemMethods = await client.services.list();
      if (op !== bindOp || closed) return;
      companionAvailable = systemMethods.some(
        (method) => method.name === "system.companion.connect" && method.available && method.granted
      );
      const own = companionAvailable ? await client.call("system.companion.status") : { connected: false, binding: null };
      if (op !== bindOp || closed || connectController) return;
      const methods = own.connected ? await client.call(
        "system.companion.list"
      ) : systemMethods;
      if (op !== bindOp || closed) return;
      const next = JSON.stringify([
        own.connected,
        own.binding,
        own.connected ? null : env.binding,
        own.connected ? null : env.connection,
        methods.filter((m) => m.name.startsWith(service + ".")).map((m) => [m.name, m.available, m.granted, m.source])
      ]);
      if (!force && signature === next) return;
      generation++;
      schemaOp++;
      pageOp++;
      pageBusy = false;
      ready = false;
      queryController?.abort();
      queryController = null;
      await cancelExport();
      if (op !== bindOp || closed) return;
      privateConnection = own.connected;
      clearResult("Run a query to see results.", false);
      const state = connectionState(env, methods, own.connected);
      if (!state.ready) {
        signature = next;
        unavailable(state.title, state.detail);
        return;
      }
      $("connection-state").textContent = "Checking database\u2026";
      const info = await call("capabilities");
      if (op !== bindOp || closed) return;
      signature = next;
      provider = info.provider;
      ready = true;
      $("setup").hidden = true;
      $("workspace").hidden = false;
      $("connection-state").textContent = "Connected";
      $("connection-state").classList.add("connected");
      $("destination").textContent = privateConnection ? destination || `${provider} \xB7 app connection` : `${provider} \xB7 ${env.host?.name ?? "workspace"}`;
      button("connection-settings").textContent = "Connection\u2026";
      status.textContent = "Ready. Choose a table or write a query.";
      setControls();
      await loadSchemas();
    } catch (error) {
      if (op === bindOp && !closed) {
        signature = null;
        unavailable("Connection unavailable", message(error));
      }
    }
  }
  function selectProvider() {
    const sqlite = input("db-provider").value === "sqlite";
    $("network-fields").hidden = sqlite;
    $("sqlite-fields").hidden = !sqlite;
    for (const id of [
      "db-host",
      "db-port",
      "db-name",
      "db-user",
      "db-password",
      "db-tls",
      "db-trust"
    ])
      input(id).disabled = sqlite;
    input("db-path").disabled = !sqlite;
    input("db-trust").disabled = sqlite || !input("db-tls").checked;
    for (const id of ["db-host", "db-port", "db-name", "db-user"])
      input(id).required = !sqlite;
    input("db-path").required = sqlite;
    input("db-port").value = String(
      {
        sqlserver: 1433,
        postgresql: 5432,
        mysql: 3306,
        mariadb: 3306
      }[input("db-provider").value] ?? 0
    );
  }
  function openConnection() {
    if (!companionAvailable) return;
    $("connect-error").hidden = true;
    dialog.showModal();
    $("db-provider").focus();
  }
  function closeConnection() {
    connectController?.abort();
    input("db-password").value = "";
    dialog.close();
  }
  async function connect(event) {
    event.preventDefault();
    if (connectController) return;
    const active = new AbortController();
    connectController = active;
    setControls();
    $("connection-fields").disabled = true;
    button("connect-submit").disabled = true;
    button("connect-submit").textContent = "Connecting\u2026";
    $("connect-error").hidden = true;
    const selected = input("db-provider").value;
    const configuration = selected === "sqlite" ? { provider: selected, sqlitePath: input("db-path").value.trim() } : {
      provider: selected,
      host: input("db-host").value.trim(),
      port: Number(input("db-port").value),
      database: input("db-name").value.trim(),
      username: input("db-user").value.trim(),
      password: input("db-password").value,
      tls: input("db-tls").checked,
      trustServerCertificate: input("db-tls").checked && input("db-trust").checked
    };
    const target = selected === "sqlite" ? input("db-path").value.trim() : `${configuration.host}:${configuration.port} / ${configuration.database}`;
    status.textContent = `Connecting to ${target}\u2026`;
    try {
      await client.call(
        "system.companion.connect",
        { configuration },
        active.signal
      );
      destination = `${$("db-provider").selectedOptions[0].text} \xB7 ${target}`;
      input("db-password").value = "";
      dialog.close();
    } catch (error) {
      if (!active.signal.aborted) {
        $("connect-error").textContent = message(error);
        $("connect-error").hidden = false;
      }
      status.textContent = active.signal.aborted ? "Connection canceled." : `Could not connect to ${target}.`;
    } finally {
      connectController = null;
      $("connection-fields").disabled = false;
      button("connect-submit").disabled = false;
      button("connect-submit").textContent = "Connect";
      await refresh(true);
    }
  }
  async function start() {
    client = await connectToShellCanvas();
    client.events.subscribe((batch) => {
      for (const event of batch.events)
        if (event.topic === "system.environment")
          applyAppearance(
            document.documentElement,
            event.value?.appearance
          );
      if (batch.events.some(
        (event) => ["system.environment", "system.services", "system.companion"].includes(
          event.topic
        )
      ))
        void refresh();
    }, report);
    window.addEventListener(
      "pagehide",
      () => {
        closed = true;
        generation++;
        bindOp++;
        queryController?.abort();
        connectController?.abort();
        client.dispose();
      },
      { once: true }
    );
    await refresh();
  }
  button("run").onclick = () => void execute();
  button("cancel").onclick = () => queryController?.abort();
  button("reload").onclick = () => void loadSchemas();
  button("export").onclick = () => void exportCsv();
  button("prev").onclick = () => {
    const offset = previousOffsets.at(-1);
    if (offset !== void 0) void move(offset, true);
  };
  button("next").onclick = () => {
    if (current) void move(nextOffset(current));
  };
  button("retry").onclick = () => void refresh(true);
  button("connection-settings").onclick = openConnection;
  button("setup-connect").onclick = openConnection;
  button("close-dialog").onclick = closeConnection;
  button("connect-cancel").onclick = closeConnection;
  dialog.addEventListener("cancel", (event) => {
    event.preventDefault();
    closeConnection();
  });
  $("connect-form").addEventListener(
    "submit",
    (event) => void connect(event)
  );
  $("db-provider").addEventListener("change", selectProvider);
  input("db-tls").addEventListener("change", () => {
    input("db-trust").disabled = !input("db-tls").checked;
  });
  button("disconnect").onclick = () => {
    void (async () => {
      queryController?.abort();
      await cancelExport();
      await client.call("system.companion.disconnect");
      destination = "";
      await refresh(true);
    })().catch(report);
  };
  sql.addEventListener("keydown", (event) => {
    if ((event.ctrlKey || event.metaKey) && event.key === "Enter") {
      event.preventDefault();
      void execute();
    }
  });
  selectProvider();
  setControls();
  void start().catch(
    (error) => unavailable("ShellCanvas connection unavailable", message(error))
  );
})();

style:
/* SPDX-License-Identifier: MPL-2.0 */
:root {
  --sc-base: #19191c;
  --sc-surface: #232326;
  --sc-raised: #303034;
  --sc-inset: #1d1d20;
  --sc-text: #e8e8ec;
  --sc-muted: #aaaab4;
  --sc-accent: #7ab8ff;
  --sc-onAccent: #14283e;
  --sc-border: #44444b;
  --sc-hover: #38383e;
  --sc-selection: #293f58;
  --sc-danger: #f2a4a4;
  --sc-dangerSoft: #482d32;
  --sc-warning: #eec778;
  --sc-success: #88cda5;
  font-family: "Segoe UI", system-ui, sans-serif;
  font-size: 13px;
  color-scheme: dark;
}
* {
  box-sizing: border-box;
}
[hidden] {
  display: none !important;
}
html,
body {
  margin: 0;
  height: 100%;
  background: var(--sc-surface);
  color: var(--sc-text);
  font:
    13px/1.5 "Segoe UI",
    system-ui,
    sans-serif;
}
button,
input,
select,
textarea {
  font: inherit;
}
button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 32px;
  padding: 6px 12px;
  border: 1px solid var(--sc-border);
  border-radius: 6px;
  background: transparent;
  color: var(--sc-text);
  cursor: pointer;
  white-space: nowrap;
}
button:hover:not(:disabled) {
  background: var(--sc-hover);
}
button:disabled {
  opacity: 0.45;
  cursor: default;
}
button.primary {
  background: var(--sc-accent);
  border-color: var(--sc-accent);
  color: var(--sc-onAccent);
  font-weight: 600;
}
button.primary:hover:not(:disabled) {
  filter: brightness(1.08);
  background: var(--sc-accent);
}
:focus-visible {
  outline: 2px solid var(--sc-accent);
  outline-offset: 2px;
}
main {
  height: 100vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
h1,
h2,
p {
  margin: 0;
}
h1 {
  font-size: 15px;
  font-weight: 600;
}
h2 {
  font-size: 13px;
  font-weight: 600;
}
svg {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
}
.app-header {
  display: flex;
  gap: 20px;
  align-items: center;
  justify-content: space-between;
  min-height: 76px;
  padding: 14px 20px;
  border-bottom: 1px solid var(--sc-border);
}
.app-heading,
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.app-heading p {
  color: var(--sc-muted);
  font-size: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 50vw;
}
.app-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--sc-accent);
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: var(--sc-selection);
  flex-shrink: 0;
}
.connection-state {
  font-size: 12px;
  color: var(--sc-muted);
  white-space: nowrap;
}
.connection-state::before {
  content: "";
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-right: 7px;
  border-radius: 50%;
  background: currentColor;
}
.connection-state.connected {
  color: var(--sc-success);
}
.setup {
  display: grid;
  place-items: center;
  flex: 1;
  overflow: auto;
  padding: 28px;
}
.setup-card {
  text-align: center;
  max-width: 490px;
}
.setup-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 64px;
  height: 64px;
  border: 1px solid var(--sc-border);
  border-radius: 16px;
  color: var(--sc-accent);
  background: var(--sc-raised);
  margin-bottom: 20px;
}
.setup-icon svg {
  width: 32px;
  height: 32px;
}
.setup h2 {
  font-size: 23px;
  font-weight: 600;
  margin-bottom: 10px;
}
.setup p {
  color: var(--sc-muted);
  line-height: 1.7;
}
.provider-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  margin: 22px 0;
}
.provider-list span {
  font-size: 11px;
  border: 1px solid var(--sc-border);
  padding: 4px 9px;
  border-radius: 5px;
  color: var(--sc-muted);
}
.setup button {
  margin: 0 3px;
}
.setup .setup-note {
  font-size: 12px;
  margin: 24px auto 0;
  max-width: 360px;
}
.workspace {
  display: grid;
  grid-template-columns: 210px minmax(0, 1fr);
  min-height: 0;
  flex: 1;
}
aside {
  background: var(--sc-inset);
  border-right: 1px solid var(--sc-border);
  padding: 16px 12px;
  overflow: auto;
}
.side-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 6px 12px;
}
.side-head h2 {
  color: var(--sc-muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.icon-button {
  padding: 0;
  min-height: 28px;
  width: 28px;
  font-size: 18px;
  border-color: transparent;
}
#tree {
  color: var(--sc-muted);
  font-size: 12px;
}
details {
  margin: 4px 0;
}
summary {
  padding: 5px 6px;
  cursor: pointer;
  color: var(--sc-text);
}
details p {
  padding: 6px 16px;
}
.table {
  display: block;
  border: 0;
  width: 100%;
  text-align: left;
  min-height: 30px;
  padding: 5px 12px 5px 25px;
  font-size: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
}
.work {
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
  min-height: 0;
}
.editor-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
}
.editor-heading span {
  font-size: 11px;
  color: var(--sc-muted);
}
textarea {
  width: 100%;
  min-height: 90px;
  height: 150px;
  max-height: 50vh;
  flex-shrink: 0;
  resize: vertical;
  border: 1px solid var(--sc-border);
  border-radius: 6px;
  background: var(--sc-inset);
  color: var(--sc-text);
  padding: 12px 14px;
  font:
    13px/1.7 Consolas,
    "Cascadia Code",
    monospace;
  tab-size: 2;
}
.toolbar,
.result-head,
.result-head > div,
.pager {
  display: flex;
  align-items: center;
  gap: 8px;
}
.query-note {
  margin-left: auto;
  color: var(--sc-muted);
  font-size: 11px;
}
.result-head {
  justify-content: space-between;
  margin-top: 10px;
}
.safe {
  font-size: 11px;
  color: var(--sc-muted);
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
input[type="checkbox"] {
  accent-color: var(--sc-accent);
}
.grid-wrap {
  overflow: auto;
  min-height: 100px;
  flex: 1;
  border: 1px solid var(--sc-border);
  border-radius: 6px;
  background: var(--sc-inset);
}
table {
  border-collapse: separate;
  border-spacing: 0;
  min-width: 100%;
  font:
    12px/1.5 Consolas,
    monospace;
}
th,
td {
  padding: 8px 12px;
  border-right: 1px solid var(--sc-border);
  border-bottom: 1px solid var(--sc-border);
  white-space: pre;
  max-width: 420px;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: left;
}
th {
  position: sticky;
  top: 0;
  background: var(--sc-raised);
  color: var(--sc-muted);
  font-weight: 500;
}
tr:hover td {
  background: var(--sc-hover);
}
.cell-null {
  color: var(--sc-muted);
  font-style: italic;
}
.cell-binary {
  color: var(--sc-accent);
}
.cell-unsupported,
#warnings {
  color: var(--sc-warning);
}
#warnings {
  font-size: 12px;
}
#empty {
  padding: 28px;
  text-align: center;
  color: var(--sc-muted);
  font-size: 12px;
}
.pager {
  justify-content: flex-end;
  font-size: 11px;
  color: var(--sc-muted);
}
.pager #page {
  margin-right: auto;
}
.pager button {
  font-size: 11px;
  min-height: 28px;
  padding: 4px 10px;
}
footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 32px;
  padding: 6px 16px;
  border-top: 1px solid var(--sc-border);
  color: var(--sc-muted);
  font-size: 11px;
}
footer > :first-child {
  overflow-wrap: anywhere;
}
footer > :last-child {
  white-space: nowrap;
}
dialog {
  color: var(--sc-text);
  background: var(--sc-surface);
  border: 1px solid var(--sc-border);
  border-radius: 14px;
  padding: 26px;
  width: min(520px, calc(100vw - 32px));
  max-height: calc(100vh - 32px);
  overflow: auto;
  box-shadow: 0 20px 70px #0006;
}
dialog::backdrop {
  background: #0007;
}
.dialog-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}
dialog h2 {
  font-size: 23px;
  margin-bottom: 8px;
}
dialog p {
  color: var(--sc-muted);
  font-size: 12px;
  line-height: 1.6;
}
fieldset {
  border: 0;
  margin: 18px 0 0;
  padding: 0;
  min-width: 0;
}
fieldset label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 12px;
  margin-bottom: 12px;
}
fieldset input:not([type="checkbox"]),
select {
  width: 100%;
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid var(--sc-border);
  border-radius: 6px;
  background: var(--sc-raised);
  color: var(--sc-text);
}
.field-row {
  display: flex;
  gap: 12px;
}
.field-row label {
  flex: 1;
  min-width: 0;
}
.field-row .port-field {
  flex: 0 0 100px;
}
fieldset .checkbox {
  flex-direction: row;
  align-items: center;
  gap: 7px;
  margin: 10px 0;
}
.field-hint {
  margin: 10px 0;
}
.dialog-actions {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: 20px;
}
.dialog-actions span {
  margin-right: auto;
  font-size: 11px;
  color: var(--sc-muted);
}
.error {
  margin-top: 14px;
  padding: 10px 12px;
  border-radius: 6px;
  background: var(--sc-dangerSoft);
  color: var(--sc-danger);
}
@media (max-width: 700px) {
  .app-header {
    padding: 12px;
    gap: 10px;
  }
  .connection-state {
    display: none;
  }
  .workspace {
    grid-template-columns: 155px minmax(0, 1fr);
  }
  .work {
    padding: 12px;
  }
  .query-note {
    display: none;
  }
  .result-head {
    align-items: flex-start;
    gap: 8px;
    flex-wrap: wrap;
  }
  .safe {
    font-size: 10px;
  }
  footer > :last-child {
    display: none;
  }
}
@media (max-width: 480px) {
  .workspace {
    grid-template-columns: 1fr;
  }
  aside {
    max-height: 145px;
    border-right: 0;
    border-bottom: 1px solid var(--sc-border);
  }
  .app-heading p {
    max-width: 40vw;
  }
  .app-header .app-icon {
    display: none;
  }
  .field-row {
    flex-wrap: wrap;
  }
}
